CREATE TABLE things (
  id INTEGER PRIMARY KEY,
  b BOOLEAN NOT NULL,
  nb BOOLEAN,
  i1 TINYINT NOT NULL,
  ni1 TINYINT,
  i2 SMALLINT NOT NULL,
  ni2 SMALLINT,
  i4 INTEGER NOT NULL,
  ni4 INTEGER,
  i8 BIGINT NOT NULL,
  ni8 BIGINT,
  u1 UTINYINT NOT NULL,
  nu1 UTINYINT,
  u2 USMALLINT NOT NULL,
  nu2 USMALLINT,
  u4 UINTEGER NOT NULL,
  nu4 UINTEGER,
  u8 UBIGINT NOT NULL,
  nu8 UBIGINT,
  h HUGEINT NOT NULL,
  nh HUGEINT,
  uh UHUGEINT NOT NULL,
  bn BIGNUM NOT NULL,
  f4 FLOAT NOT NULL,
  nf4 FLOAT,
  f8 DOUBLE NOT NULL,
  nf8 DOUBLE,
  d DECIMAL(18,4) NOT NULL,
  nd DECIMAL(18,4),
  n NUMERIC NOT NULL,
  s VARCHAR NOT NULL,
  ns VARCHAR,
  t TEXT NOT NULL,
  bl BLOB NOT NULL,
  nbl BLOB,
  dt DATE NOT NULL,
  ndt DATE,
  tm TIME NOT NULL,
  ntm TIME,
  ts TIMESTAMP NOT NULL,
  nts TIMESTAMP,
  tstz TIMESTAMPTZ NOT NULL,
  ntstz TIMESTAMPTZ,
  tsns TIMESTAMP_NS NOT NULL,
  iv INTERVAL NOT NULL,
  niv INTERVAL,
  u UUID NOT NULL,
  nu UUID,
  j JSON NOT NULL,
  nj JSON,
  e ENUM('a', 'b') NOT NULL,
  ne ENUM('a', 'b'),
  li INTEGER[] NOT NULL,
  nli INTEGER[],
  ls VARCHAR[] NOT NULL,
  lu UUID[],
  lj JSON[],
  fixed INTEGER[3],
  st STRUCT(a INTEGER, b VARCHAR) NOT NULL,
  nst STRUCT(a INTEGER, b VARCHAR),
  m MAP(VARCHAR, INTEGER) NOT NULL,
  nm MAP(VARCHAR, INTEGER)
);
